func (e *DecodeError) Error() string {
	return "toml: " + e.message
}

func (e *DecodeError) String() string {
	return e.human
}

func (e *DecodeError) Position() (row int, column int) {
	return e.line, e.column
}

func (e *DecodeError) Key() Key {
	return e.key
}

func (p *Program) Execute() {
	flag.Usage = func() { fmt.Fprint(os.Stderr, p.Usage) }
	flag.Parse()
	os.Exit(p.main(flag.Args(), os.Stdin, os.Stdout, os.Stderr))
}

func (p *Program) main(files []string, input io.Reader, output, stderr io.Writer) int {
	err := p.run(files, input, output)
	if err != nil {
		var derr *toml.DecodeError
		if errors.As(err, &derr) {
			_, _ = fmt.Fprintln(stderr, derr.String())
			row, col := derr.Position()
			_, _ = fmt.Fprintln(stderr, "error occurred at row", row, "column", col)
		} else {
			_, _ = fmt.Fprintln(stderr, err.Error())
		}

		return -1
	}
	return 0
}

func (p *Program) run(files []string, input io.Reader, output io.Writer) error {
	if len(files) > 0 {
		if p.Inplace {
			return p.runAllFilesInPlace(files)
		}
		f, err := os.Open(files[0])
		if err != nil {
			return err
		}
		defer func() { _ = f.Close() }()
		input = f
	}
	return p.Fn(input, output)
}

func (p *Program) runAllFilesInPlace(files []string) error {
	for _, path := range files {
		err := p.runFileInPlace(path)
		if err != nil {
			return err
		}
	}
	return nil
}

func (p *Program) runFileInPlace(path string) error {
	in, err := os.ReadFile(path) // #nosec G304
	if err != nil {
		return err
	}

	out := new(bytes.Buffer)

	err = p.Fn(bytes.NewReader(in), out)
	if err != nil {
		return err
	}

	return os.WriteFile(path, out.Bytes(), 0o600)
}

func (t *KeyTracker) UpdateTable(node *unstable.Node) {
	t.Reset()
	t.Push(node)
}

func (t *KeyTracker) UpdateArrayTable(node *unstable.Node) {
	t.Reset()
	t.Push(node)
}

func (t *KeyTracker) Push(node *unstable.Node) {
	it := node.Key()
	for it.Next() {
		t.k = append(t.k, it.Node().Data)
	}
}

func (t *KeyTracker) Pop(node *unstable.Node) {
	it := node.Key()
	for it.Next() {
		t.k = t.k[:len(t.k)-1]
	}
}

func (t *KeyTracker) PushParts(parts [][]byte) {
	t.k = append(t.k, parts...)
}

func (t *KeyTracker) PopN(n int) {
	t.k = t.k[:len(t.k)-n]
}

func (t *KeyTracker) Key() []string {
	k := make([]string, len(t.k))
	for i, b := range t.k {
		k[i] = string(b)
	}
	return k
}

func (t *KeyTracker) Reset() {
	t.k = t.k[:0]
}

func (e *entry) spilled() bool {
	return e.childCount > spillThreshold
}

func (e *encoderState) propsFor(t reflect.Type) typeEncProps {
	if p, ok := builtinEncProps(t); ok {
		return p
	}
	if e.propsMemo[0].t == t {
		return e.propsMemo[0].p
	}
	for i := 1; i < len(e.propsMemo); i++ {
		if e.propsMemo[i].t == t {
			m := e.propsMemo[i]
			copy(e.propsMemo[1:i+1], e.propsMemo[:i])
			e.propsMemo[0] = m
			return m.p
		}
	}
	p := encPropsForType(t)
	copy(e.propsMemo[1:], e.propsMemo[:len(e.propsMemo)-1])
	e.propsMemo[0].t, e.propsMemo[0].p = t, p
	return p
}

func (e *encoderState) classify(ent *entry) entryClass {
	if e.tablesInline || ent.options.inline {
		return classKeyValue
	}
	if ent.pf != nil && ent.pf.classKnown {
		return ent.pf.staticClass
	}
	if ent.anyValue != nil {
		switch v := ent.anyValue.(type) {
		case map[string]interface{}:
			return classTable
		case []interface{}:
			if len(v) == 0 {
				return classKeyValue
			}
			for _, elem := range v {
				if _, ok := elem.(map[string]interface{}); !ok {
					// Mixed or exotic elements: decide like the reflection
					// path would (resolving pointers and interfaces).
					if e.isArrayOfTables(reflect.ValueOf(ent.anyValue)) {
						return classArrayTable
					}
					return classKeyValue
				}
			}
			return classArrayTable
		case time.Time, LocalDate, LocalTime, LocalDateTime:
			return classKeyValue
		default:
			// Not a generic container: classify through reflection.
			v2 := reflect.ValueOf(ent.anyValue)
			if e.isArrayOfTables(v2) {
				return classArrayTable
			}
			if e.isTableLike(v2) {
				return classTable
			}
			return classKeyValue
		}
	}
	if e.isArrayOfTables(ent.value) {
		return classArrayTable
	}
	if e.isTableLike(ent.value) {
		return classTable
	}
	return classKeyValue
}

func (e *encoderState) encodeRoot(v interface{}) error {
	if v == nil {
		return errors.New("toml: cannot encode a nil interface")
	}

	if m, ok := v.(map[string]interface{}); ok {
		// Generic documents skip reflection entirely: their entries are
		// collected natively and every value encodes by type switch.
		entries := e.getEntries()
		for key, value := range m {
			if value == nil {
				// nil interface values are skipped
				continue
			}
			entries = append(entries, entry{key: key, anyValue: value, options: &zeroValueOptions})
		}
		if len(entries) > 1 {
			slices.SortFunc(entries, func(a, b entry) int {
				return strings.Compare(a.key, b.key)
			})
		}
		return e.encodeEntries(entries, false, 0)
	}

	rv := reflect.ValueOf(v)
	rv, ok := resolve(rv)
	if !ok {
		return errors.New("toml: cannot encode a nil pointer")
	}

	switch rv.Kind() {
	case reflect.Map, reflect.Struct:
		if isValueKind(rv) {
			return fmt.Errorf("toml: cannot encode a %s as a document root", rv.Type())
		}
		return e.encodeTable(rv, false, 0)
	default:
		return fmt.Errorf("toml: cannot encode a %s as a document root", rv.Type())
	}
}

func builtinEncProps(t reflect.Type) (typeEncProps, bool) {
	switch t.Kind() {
	case reflect.String:
		if t == stringType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Bool:
		if t == boolType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Int:
		if t == intType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Int64:
		if t == int64Type {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Float64:
		if t == float64Type {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Slice:
		if t == sliceInterfaceType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Map:
		if t == mapStringInterfaceType {
			return typeEncProps{isValue: false}, true
		}
	}
	return typeEncProps{}, false
}

func encPropsForType(t reflect.Type) typeEncProps {
	if p, ok := builtinEncProps(t); ok {
		return p
	}
	if p, ok := typeEncPropsCache.Load(t); ok {
		return p.(typeEncProps)
	}
	var p typeEncProps
	switch {
	case t.Implements(textMarshalerType):
		p.text = 1
	case reflect.PtrTo(t).Implements(textMarshalerType):
		p.text = 2
	}
	switch t {
	case timeType, localDateType, localTimeType, localDateTimeType:
		p.isValue = true
	default:
		if p.text != 0 {
			p.isValue = true
		} else {
			switch t.Kind() {
			case reflect.Map, reflect.Struct:
				p.isValue = false
			default:
				p.isValue = true
			}
		}
	}
	typeEncPropsCache.Store(t, p)
	return p
}

func (e *encoderState) isTableLike(v reflect.Value) bool {
	v, ok := resolve(v)
	if !ok {
		// Unresolvable values (interface-held nil pointers) are encoded as
		// the zero value of their element type by the value path.
		return false
	}
	return !e.propsFor(v.Type()).isValue
}

func (e *encoderState) isArrayOfTables(v reflect.Value) bool {
	v, ok := resolve(v)
	if !ok {
		return false
	}
	if v.Kind() != reflect.Slice && v.Kind() != reflect.Array {
		return false
	}
	if v.Len() == 0 {
		return false
	}
	for i := 0; i < v.Len(); i++ {
		elem, ok := resolve(v.Index(i))
		if !ok || e.propsFor(elem.Type()).isValue {
			return false
		}
	}
	return true
}

func (e *encoderState) encodeTable(v reflect.Value, commented bool, indent int) error {
	entries, err := e.collectEntries(v)
	if err != nil {
		return err
	}
	return e.encodeEntries(entries, commented, indent)
}

func (e *encoderState) encodeEntries(entries []entry, commented bool, indent int) error {
	// First pass: emit all key-values; tables are handled by the second
	// pass.
	for i := range entries {
		ent := &entries[i]
		ent.class = e.classify(ent)
		if ent.class != classKeyValue {
			continue
		}
		err := e.encodeKeyValue(ent, commented, indent)
		if err != nil {
			return err
		}
	}

	// Second pass: emit the sub-tables, extending the shared key stack.
	for i := range entries {
		ent := entries[i]
		if ent.class == classKeyValue {
			continue
		}
		if ent.anyValue != nil {
			// Tables recurse through the reflection walk; their own entries
			// are collected natively again at the next level.
			ent.value = reflect.ValueOf(ent.anyValue)
			ent.anyValue = nil
		}
		entCommented := commented || ent.options.commented
		bare := ent.pf != nil && ent.pf.bareKey
		if !bare {
			bare = isBareKey(ent.key)
		}
		e.keyStack = append(e.keyStack, keyStackPart{s: ent.key, bare: bare})

		if ent.class == classArrayTable {
			err := e.encodeArrayTable(&ent, entCommented, indent)
			if err != nil {
				return err
			}
			e.keyStack = e.keyStack[:len(e.keyStack)-1]
			continue
		}

		// The value is resolvable: classify already resolved it.
		tv, _ := resolve(ent.value)

		e.writeTableHeader(ent.options.comment, entCommented, false, indent)

		err := e.encodeTable(tv, entCommented, indent+1)
		if err != nil {
			return err
		}
		e.keyStack = e.keyStack[:len(e.keyStack)-1]
	}

	e.putEntries(entries)
	return nil
}

func (e *encoderState) getEntries() []entry {
	if n := len(e.entriesPool); n > 0 {
		s := e.entriesPool[n-1]
		e.entriesPool = e.entriesPool[:n-1]
		return s[:0]
	}
	return nil
}

func (e *encoderState) putEntries(s []entry) {
	if cap(s) > 0 {
		e.entriesPool = append(e.entriesPool, s)
	}
}

func (e *encoderState) encodeArrayTable(ent *entry, commented bool, indent int) error {
	v, _ := resolve(ent.value)
	comment := ent.options.comment
	for i := 0; i < v.Len(); i++ {
		// Elements are resolvable: isArrayOfTables already resolved them.
		elem, _ := resolve(v.Index(i))

		e.writeTableHeader(comment, commented, true, indent)
		// The comment is only present before the first element.
		comment = ""

		err := e.encodeTable(elem, commented, indent+1)
		if err != nil {
			return err
		}
	}
	return nil
}

func (e *encoderState) writeTableHeader(comment string, commented bool, array bool, indent int) {
	key := e.keyStack
	if len(e.buf) > 0 && !e.lastWasHeader {
		e.buf = append(e.buf, '\n')
	}

	headerIndent := indent

	e.writeComment(comment, headerIndent)

	// The "commented" marker is emitted at column zero, ahead of any table
	// indentation, so that the indentation appears inside the comment
	// (e.g. `#   [a.b]`). This matches the historical v2.3 layout.
	if commented {
		e.buf = append(e.buf, "# "...)
	}
	e.writeIndent(headerIndent)
	e.buf = append(e.buf, '[')
	if array {
		e.buf = append(e.buf, '[')
	}
	for i, part := range key {
		if i > 0 {
			e.buf = append(e.buf, '.')
		}
		if part.bare {
			e.buf = append(e.buf, part.s...)
		} else {
			e.buf = e.appendString(e.buf, part.s)
		}
	}
	e.buf = append(e.buf, ']')
	if array {
		e.buf = append(e.buf, ']')
	}
	e.buf = append(e.buf, '\n')
	e.lastWasHeader = true
}

func (e *encoderState) writeIndent(indent int) {
	if !e.indentTables {
		return
	}
	for i := 0; i < indent; i++ {
		e.buf = append(e.buf, e.indentSymbol...)
	}
}

func (e *encoderState) writeComment(comment string, indent int) {
	if comment == "" {
		return
	}
	for _, line := range strings.Split(comment, "\n") {
		e.writeIndent(indent)
		e.buf = append(e.buf, "# "...)
		e.buf = append(e.buf, line...)
		e.buf = append(e.buf, '\n')
	}
}

func (e *encoderState) encodeKeyValue(ent *entry, commented bool, indent int) error {
	commented = commented || ent.options.commented

	e.writeComment(ent.options.comment, indent)

	// The "commented" marker is emitted at column zero, ahead of any table
	// indentation, so that the indentation appears inside the comment
	// (e.g. `#   key = value`). This matches the historical v2.3 layout.
	lineStart := len(e.buf)
	if commented {
		e.buf = append(e.buf, "# "...)
	}
	e.writeIndent(indent)
	if ent.pf != nil && ent.pf.bareKey {
		e.buf = append(e.buf, ent.key...)
	} else {
		e.buf = e.appendKey(e.buf, ent.key)
	}
	e.buf = append(e.buf, " = "...)

	// When tables are not indented, the key is emitted at column zero
	// regardless of its nesting depth. Value continuation lines (most
	// notably the elements of a multiline array) must line up with that key,
	// so the value indentation starts from zero as well rather than from the
	// table nesting depth.
	valueIndent := indent
	if !e.indentTables {
		valueIndent = 0
	}

	var err error
	if ent.anyValue != nil {
		e.buf, err = e.appendAnyValue(e.buf, ent.anyValue, *ent.options, valueIndent)
	} else if ent.pf != nil && ent.pf.propsKnown {
		e.buf, err = e.appendValueProps(e.buf, ent.value, ent.pf.props, *ent.options, valueIndent)
	} else {
		e.buf, err = e.appendValue(e.buf, ent.value, *ent.options, valueIndent)
	}
	if err != nil {
		return err
	}

	// A commented value that renders across multiple lines (a multiline string
	// or a multiline array) must have every physical line prefixed with the
	// comment marker, not just the first; otherwise the continuation lines are
	// emitted as live, syntactically invalid TOML.
	if commented {
		if bytes.IndexByte(e.buf[lineStart:], '\n') >= 0 {
			region := bytes.ReplaceAll(
				append([]byte(nil), e.buf[lineStart:]...),
				[]byte("\n"), []byte("\n# "),
			)
			e.buf = append(e.buf[:lineStart], region...)
		}
	}
	e.buf = append(e.buf, '\n')
	e.lastWasHeader = false
	return nil
}

func (e *encoderState) collectEntries(v reflect.Value) ([]entry, error) {
	switch v.Kind() {
	case reflect.Map:
		return e.collectMapEntries(v)
	case reflect.Struct:
		entries := e.getEntries()
		e.collectStructEntries(&entries, v)
		return entries, nil
	default:
		return nil, fmt.Errorf("toml: cannot encode a %s as a table", v.Type())
	}
}

func (e *encoderState) collectMapEntries(v reflect.Value) ([]entry, error) {
	entries := e.getEntries()

	// Generic maps iterate natively: no per-entry reflect values at all.
	if v.Type() == mapStringInterfaceType {
		for key, value := range v.Interface().(map[string]interface{}) {
			if value == nil {
				// nil interface values are skipped
				continue
			}
			entries = append(entries, entry{key: key, anyValue: value, options: &zeroValueOptions})
		}
		if len(entries) > 1 {
			slices.SortFunc(entries, func(a, b entry) int {
				return strings.Compare(a.key, b.key)
			})
		}
		return entries, nil
	}

	// Keys are converted to strings right away: read them into a reusable
	// buffer to avoid one allocation per key.
	var kbuf reflect.Value
	plainStringKey := v.Type().Key() == stringType
	if plainStringKey {
		if !e.stringKeyBuf.IsValid() {
			e.stringKeyBuf = reflect.New(stringType).Elem()
		}
		kbuf = e.stringKeyBuf
	} else {
		kbuf = reflect.New(v.Type().Key()).Elem()
	}

	// Larger maps read their values into one slab (instead of iter.Value(),
	// which allocates a fresh value per entry). The slab elements are
	// addressable and stay alive with the entries that reference them. Small
	// maps are not worth the slab allocation.
	var slab reflect.Value
	if v.Len() >= 8 {
		slab = reflect.MakeSlice(reflect.SliceOf(v.Type().Elem()), v.Len(), v.Len())
	}
	i := 0

	iter := &e.mapIter
	iter.Reset(v)
	for iter.Next() {
		kbuf.SetIterKey(iter)
		var key string
		if plainStringKey {
			// Plain strings cannot implement TextMarshaler: skip the
			// interface checks of mapKeyString.
			key = kbuf.String()
		} else {
			var err error
			key, err = mapKeyString(kbuf)
			if err != nil {
				iter.Reset(reflect.Value{})
				return nil, err
			}
		}
		var value reflect.Value
		if slab.IsValid() && i < slab.Len() {
			value = slab.Index(i)
			i++
			value.SetIterValue(iter)
		} else {
			value = iter.Value()
		}
		if value.Kind() == reflect.Interface && value.IsNil() {
			// nil interface values are skipped
			continue
		}
		if value.Kind() == reflect.Ptr && value.IsNil() {
			// nil pointers in maps are encoded as their zero value
			value = reflect.New(value.Type().Elem()).Elem()
		}
		entries = append(entries, entry{key: key, value: value, options: &zeroValueOptions})
	}
	// Drop the map reference: the iterator lives on in the pooled state.
	iter.Reset(reflect.Value{})

	if len(entries) > 1 {
		// slices.SortFunc avoids boxing the slice into a sort.Interface (an
		// allocation that sort.Sort incurs for every table).
		slices.SortFunc(entries, func(a, b entry) int {
			return strings.Compare(a.key, b.key)
		})
	}

	return entries, nil
}

func (e *encoderState) collectStructEntries(entries *[]entry, v reflect.Value) {
	plan := encPlanForType(v.Type())

	for i := range plan.fields {
		f := &plan.fields[i]
		fv, ok := fieldByIndexSkipNil(v, f.index)
		if !ok {
			// nil embedded pointer on the way: skipped
			continue
		}

		// Anonymous interface fields that are nil are skipped.
		if fv.Kind() == reflect.Interface && fv.IsNil() {
			continue
		}
		// nil values in struct fields are skipped
		if (fv.Kind() == reflect.Ptr || fv.Kind() == reflect.Map) && fv.IsNil() {
			continue
		}

		if f.options.omitempty && isEmptyValue(fv) {
			continue
		}
		if f.options.omitzero && isZeroValue(fv) {
			continue
		}

		*entries = append(*entries, entry{key: f.name, value: fv, options: &f.options, pf: f})
	}
}

func (e *encoderState) appendKey(b []byte, key string) []byte {
	if isBareKey(key) {
		return append(b, key...)
	}
	return e.appendString(b, key)
}

func (e *encoderState) appendAnyValue(b []byte, v interface{}, opts valueOptions, indent int) ([]byte, error) {
	if v == nil {
		return nil, errors.New("toml: cannot encode a nil interface")
	}
	switch tv := v.(type) {
	case string:
		if opts.multiline && strings.IndexByte(tv, '\n') >= 0 {
			return e.appendMultilineString(b, tv), nil
		}
		return e.appendString(b, tv), nil
	case bool:
		if tv {
			return append(b, "true"...), nil
		}
		return append(b, "false"...), nil
	case int64:
		return strconv.AppendInt(b, tv, 10), nil
	case int:
		return strconv.AppendInt(b, int64(tv), 10), nil
	case float64:
		return appendFloat(b, tv, 64), nil
	case time.Time:
		return tv.AppendFormat(b, "2006-01-02T15:04:05.999999999Z07:00"), nil
	case LocalDate:
		return append(b, tv.String()...), nil
	case LocalTime:
		return append(b, tv.String()...), nil
	case LocalDateTime:
		return append(b, tv.String()...), nil
	case []interface{}:
		return e.appendAnyArray(b, tv, opts, indent)
	case map[string]interface{}:
		return e.appendInlineTable(b, reflect.ValueOf(tv), indent)
	default:
		return e.appendValue(b, reflect.ValueOf(v), opts, indent)
	}
}

func (e *encoderState) appendAnyArray(b []byte, v []interface{}, opts valueOptions, indent int) ([]byte, error) {
	multiline := opts.multiline || e.arraysMultiline

	b = append(b, '[')
	if multiline && len(v) > 0 {
		for i, elem := range v {
			if i > 0 {
				b = append(b, ',')
			}
			b = append(b, '\n')
			for j := 0; j <= indent; j++ {
				b = append(b, e.indentSymbol...)
			}
			var err error
			b, err = e.appendAnyValue(b, elem, valueOptions{}, indent+1)
			if err != nil {
				return nil, err
			}
		}
		b = append(b, '\n')
		for j := 0; j < indent; j++ {
			b = append(b, e.indentSymbol...)
		}
	} else {
		for i, elem := range v {
			if i > 0 {
				b = append(b, ", "...)
			}
			var err error
			b, err = e.appendAnyValue(b, elem, valueOptions{}, indent)
			if err != nil {
				return nil, err
			}
		}
	}
	return append(b, ']'), nil
}

func (e *encoderState) appendValue(b []byte, v reflect.Value, opts valueOptions, indent int) ([]byte, error) {
	return e.appendValueProps(b, v, e.propsFor(v.Type()), opts, indent)
}

func (e *encoderState) appendValueProps(b []byte, v reflect.Value, props typeEncProps, opts valueOptions, indent int) ([]byte, error) {
	t := v.Type()

	// Special types take precedence over their kind. All of them are structs
	// except json.Number: dispatching on the kind first keeps the common
	// scalars away from the interface comparisons.
	switch v.Kind() {
	case reflect.Struct:
		switch t {
		case timeType:
			return v.Interface().(time.Time).AppendFormat(b, "2006-01-02T15:04:05.999999999Z07:00"), nil
		case localDateType:
			return append(b, v.Interface().(LocalDate).String()...), nil
		case localTimeType:
			return append(b, v.Interface().(LocalTime).String()...), nil
		case localDateTimeType:
			return append(b, v.Interface().(LocalDateTime).String()...), nil
		}
	case reflect.String:
		if e.marshalJSONNumbers && t == jsonNumberType {
			return appendJSONNumber(b, v.Interface().(json.Number))
		}
	}

	switch props.text {
	case 1:
		if t.Kind() != reflect.String {
			return e.appendTextMarshaler(b, v.Interface().(encoding.TextMarshaler))
		}
	case 2:
		if v.CanAddr() {
			return e.appendTextMarshaler(b, v.Addr().Interface().(encoding.TextMarshaler))
		}
		tmp := reflect.New(t)
		tmp.Elem().Set(v)
		return e.appendTextMarshaler(b, tmp.Interface().(encoding.TextMarshaler))
	}

	switch v.Kind() {
	case reflect.Ptr:
		if v.IsNil() {
			// nil pointers are encoded as the zero value of their element
			// type.
			return e.appendValue(b, reflect.Zero(t.Elem()), opts, indent)
		}
		return e.appendValue(b, v.Elem(), opts, indent)
	case reflect.Interface:
		if v.IsNil() {
			return nil, errors.New("toml: cannot encode a nil interface")
		}
		return e.appendValue(b, v.Elem(), opts, indent)
	case reflect.String:
		s := v.String()
		// The "multiline" option only takes effect when the string actually
		// contains a newline. Wrapping a single-line value such as "2" in a
		// """...""" block adds noise without improving readability, so it is
		// emitted as a regular single-line string instead.
		if opts.multiline && strings.IndexByte(s, '\n') >= 0 {
			return e.appendMultilineString(b, s), nil
		}
		return e.appendString(b, s), nil
	case reflect.Bool:
		if v.Bool() {
			return append(b, "true"...), nil
		}
		return append(b, "false"...), nil
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return strconv.AppendInt(b, v.Int(), 10), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		u := v.Uint()
		if u > math.MaxInt64 {
			return nil, fmt.Errorf("toml: cannot encode an unsigned integer above math.MaxInt64: %d", u)
		}
		return strconv.AppendUint(b, u, 10), nil
	case reflect.Float32:
		return appendFloat(b, v.Float(), 32), nil
	case reflect.Float64:
		return appendFloat(b, v.Float(), 64), nil
	case reflect.Slice, reflect.Array:
		return e.appendArray(b, v, opts, indent)
	case reflect.Map:
		return e.appendInlineTable(b, v, indent)
	case reflect.Struct:
		return e.appendInlineTable(b, v, indent)
	default:
		return nil, fmt.Errorf("toml: cannot encode value of type %s", v.Type())
	}
}

func (e *encoderState) appendTextMarshaler(b []byte, m encoding.TextMarshaler) ([]byte, error) {
	text, err := m.MarshalText()
	if err != nil {
		return nil, fmt.Errorf("toml: error calling MarshalText: %w", err)
	}
	return e.appendString(b, string(text)), nil
}

func (e *encoderState) appendArray(b []byte, v reflect.Value, opts valueOptions, indent int) ([]byte, error) {
	multiline := opts.multiline || e.arraysMultiline

	b = append(b, '[')
	if multiline && v.Len() > 0 {
		for i := 0; i < v.Len(); i++ {
			if i > 0 {
				b = append(b, ',')
			}
			b = append(b, '\n')
			for j := 0; j <= indent; j++ {
				b = append(b, e.indentSymbol...)
			}
			var err error
			b, err = e.appendValue(b, v.Index(i), valueOptions{}, indent+1)
			if err != nil {
				return nil, err
			}
		}
		b = append(b, '\n')
		for j := 0; j < indent; j++ {
			b = append(b, e.indentSymbol...)
		}
	} else {
		for i := 0; i < v.Len(); i++ {
			if i > 0 {
				b = append(b, ", "...)
			}
			var err error
			b, err = e.appendValue(b, v.Index(i), valueOptions{}, indent)
			if err != nil {
				return nil, err
			}
		}
	}
	return append(b, ']'), nil
}

func (e *encoderState) appendInlineTable(b []byte, v reflect.Value, indent int) ([]byte, error) {
	entries, err := e.collectEntries(v)
	if err != nil {
		return nil, err
	}

	b = append(b, '{')
	for i, ent := range entries {
		if i > 0 {
			b = append(b, ", "...)
		}
		b = e.appendKey(b, ent.key)
		b = append(b, " = "...)
		// multiline strings are not allowed inside inline tables: they
		// would break the single-line requirement.
		opts := *ent.options
		opts.multiline = false
		if ent.anyValue != nil {
			b, err = e.appendAnyValue(b, ent.anyValue, opts, indent)
		} else {
			b, err = e.appendValue(b, ent.value, opts, indent)
		}
		if err != nil {
			return nil, err
		}
	}
	e.putEntries(entries)
	return append(b, '}'), nil
}

func (e *encoderState) appendString(b []byte, s string) []byte {
	if canBeLiteral(s) {
		b = append(b, '\'')
		b = append(b, s...)
		return append(b, '\'')
	}
	return appendBasicString(b, s)
}

func (e *encoderState) appendMultilineString(b []byte, s string) []byte {
	return appendMultilineString(b, s)
}

func (p *pathPart) bytes() []byte {
	if p.node != nil {
		return p.node.Data
	}
	if p.data != nil {
		return p.data
	}
	return []byte(p.name)
}

func (p *pathPart) str() string {
	if p.node != nil {
		return string(p.node.Data)
	}
	if p.data != nil {
		return string(p.data)
	}
	return p.name
}

func (e *typeMismatchError) Error() string {
	return fmt.Sprintf("cannot decode TOML %s into %s", e.toml, e.target)
}

func (p *structPlan) lookup(name string) (structField, bool) {
	if p.hasCollision {
		if f, ok := p.byName[name]; ok {
			return f, true
		}
	}
	if f, ok := p.byFold[name]; ok {
		return f, true
	}
	return p.lookupFoldStr(name)
}

func (p *structPlan) lookupBytes(name []byte) (structField, bool) {
	if p.hasCollision {
		if f, ok := p.byName[string(name)]; ok { // does not allocate
			return f, true
		}
	}
	if f, ok := p.byFold[string(name)]; ok { // does not allocate
		return f, true
	}
	return p.lookupFold(name)
}

func (p *structPlan) lookupFold(name []byte) (structField, bool) {
	if len(name) <= foldBufSize {
		// Fold into a stack buffer: len(name) <= cap(buf), so the append
		// never reallocates and nothing escapes to the heap.
		var buf [foldBufSize]byte
		b := buf[:0]
		ascii := true
		for _, c := range name {
			if c >= 0x80 {
				ascii = false
				break
			}
			if c >= 'A' && c <= 'Z' {
				c += 'a' - 'A'
			}
			b = append(b, c)
		}
		if ascii {
			f, ok := p.byFold[string(b)] // does not allocate
			return f, ok
		}
	}
